inputs = ['ic', 'ghaiix', 'xayf', 'gvei', 'vbeb']
outputs = ['wc', 'ghawwx', 'xayf', 'gvew', 'vuyeuy']

# Let me create a more detailed analysis
print("Detailed Analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{i}: '{inp}' -> '{out}'")
    if inp != out:
        # Find all character differences
        diff_positions = []
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_positions.append((j, inp[j], out[j]))

        if len(inp) != len(out):
            # Different lengths - check if it's insertion/deletion
            if len(out) > len(inp):
                # Insertion case
                print(f"  Insertion detected: added {len(out) - len(inp)} chars")
            else:
                # Deletion case
                print(f"  Deletion detected: removed {len(inp) - len(out)} chars")
        else:
            # Same length - character changes
            for pos, old_char, new_char in diff_positions:
                print(f"  Position {pos}: '{old_char}' -> '{new_char}'")
    print()

